-- pipeline/claim-run
-- The worker takes the oldest queued run and marks it running. `skip locked` keeps two workers from taking the same run.
--
-- No parameters.
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

update pipeline_runs set status = 'running', started_at = now(), updated_at = now()
where id = (select id from pipeline_runs where status = 'queued' order by created_at limit 1 for update skip locked)
returning id, trigger;
